    }

    try {
        if (!ticketKey) throw new Error('params.ticket.key is missing');
        console.log('=== Bug done check for', ticketKey, '===');

        const ticket = getTicket();
        const labels = (ticket && ticket.fields && ticket.fields.labels) || [];

