                '`discovery.space` / `discovery.parentPageId` are not configured for this project. ' +
                'Set them in `.dmtools/config.js` to enable publishing.';
            console.warn(msg);
            try {
                tracker.postComment(ticketKey, 'h3. ⚠️ Discovery drafted, not published\n\n' + msg);
            } catch (commentError) {
                console.warn('Failed to post not-configured comment:', commentError);
            }
            return result;
        }

        var children;
        try {
            children = confluence_get_children_by_id({ contentId: parentPageId, format: 'md' });
        } catch (e) {
            console.error('Failed to list children of parentPageId', parentPageId, ':', e);
            result.action = 'children_lookup_failed';
            result.error = e.toString();
            return result;
        }

        var page = findTicketPage(children, ticketKey);
        if (!page) {
            console.log('No existing discovery page for ' + ticketKey + ' — c…

/**
 * Fetch Confluence Output Context — pre-CLI action for content-generating
 * agents (story_description, story_acceptance_criteria, story_solution).
 *
 * When customParams.contentOutput targets Confluence (target: 'confluence' or
 * 'both') and a page for this ticket already exists under
 * contentOutput.parentPageId, this:
 *   1. Writes the page's current body to input/confluence_output_current.md so
 *      the CLI agent iterates on prior content instead of rewriting blindly.
 *   2. If contentOutput.includeInlineComments is not false, fetches the page's
 *      inline comments into input/confluence_output_comments.json and .md so
 *      the agent can treat them as review feedback and answer them via
 *      outputs/confluence_replies.json (published by writeContentOutput.js).
 *
 * On every Confluence-targeted run (including the first one, when no page
 * exists yet) it also writes input/confluence_output_target.json — a marker
 * the CLI agent uses to know the output is headed to a Confluence page and
 * must be written as Markdown rather than tracker markup.
 *
 * No-op when the target is jira_field or Confluence is not configured.
 * All errors are non-fatal.
 */

var contentOutput = require('./common/contentOutput.js');

var CURRENT_CONTENT_FILE = 'confluence_output_current.md';
var TARGET_MARKER_FILE = 'confluence_output_target.json';

function action(params) {
    var folder = params.inputFolderPath;
    var ticket = params.ticket || {};
    var ticketKey = ticket.key || (folder ? folder.split('/').pop() : null);

    try {
        var cfg = contentOutput.resolveConfig(params);
        if (!contentOutput.isConfluenceTarget(cfg)) {
            return { success: true, action: 'skipped_not_confluence_target' };
        }
        if (!cfg.space || !cfg.parentPageId) {
            console.warn('contentOutput.space / contentOutput.parentPageId not configured — skipping Confluence context fetch');
            return { success: true, action: 'skipped_not_configured' };
        }

        // Always write the target marker so the CLI agent knows the output is
        // headed to Confluence (Markdown, not tracker markup) — even on the
        // first run when no page exists yet.
        var pageTitle = contentOutput.buildPageTitle(cfg, ticketKey,
            (ticket.fields && ticket.fields.summary) || '');
        if (folder) {
            try {
                file_write(folder + '/' + TARGET_MARKER_FILE, JSON.stringify({
                    target: cfg.target,
                    format: 'markdown',
                    pageTitle: pageTitle,
                    space: cfg.space,
                    parentPageId: cfg.parentPageId
                }, null, 2));
            } catch (markerError) {
                console.warn('fetchConfluenceOutputContext: failed to write target marker:', markerError);
            }
        }

        var children;
        try {
            children = confluence_get_children_by_id({ contentId: cfg.parentPageId, format: 'md' });
        } catch (e) {
            console.warn('fetchConfluenceOutputContext: failed to list children of ' + cfg.parentPageId + ':', e);
            return { success: false, action: 'children_lookup_failed', error: e.toString() };
        }

        var existing = contentOutput.findTicketPage(children, ticketKey);
        if (!existing) {
            console.log('No existing Confluence page for ' + ticketKey + ' — first run, no context to fetch');
            return { success: true, action: 'first_run', pageTitle: pageTitle };
        }

        var pageTitle = existing.title || ticketKey;

        // 1. Current page body
        try {
            var body = (existing.body && existing.body.storage && existing.body.storage.value) || '';
            if (!body) {
                var full = confluence_content_by_id({ contentId: existing.id, format: 'md' });
                body = (full && full.body && full.body.storage && full.body.storage.value) || '';
            }
            if (folder && body) {
                // Preserve inline comment anchors: storage bodies carry them as
                // <ac:inline-comment-marker> elements which the Markdown conversion
                // strips. Re-expose them as [[ic:REF]]...[[/ic]] placeholders so the
                // agent can keep the anchors in its output (publishPage converts them
                // back after the sync).
                try {
                    var storage = confluence_content_by_id({ contentId: existing.id });
                    var storageBody = storage && storage.body && storage.body.storage && storage.body.storage.value;
                    var anchors = contentOutput.extractInlineCommentMarkers(storageBody);
                    if (anchors.length > 0) {
                        var injected = contentOutput.injectCommentPlaceholders(body, anchors);
                        body = injected.content;
                        console.log('fetchConfluenceOutputContext: injected ' + injected.injected.length +
                            ' inline comment placeholder(s)' +
                            (injected.missed.length > 0 ? ', ' + injected.missed.length + ' anchor text(s) not found in Markdown' : ''));
                    }
                } catch (markerError) {
                    console.warn('fetchConfluenceOutputContext: marker extraction failed (non-fatal):', markerError);
                }
                file_write(folder + '/' + CURRENT_CONTENT_FILE, body);
                console.log('Wrote current page content to input/' + CURRENT_CONTENT_FILE);
            }
        } catch (e) {
            console.warn('fetchConfluenceOutputContext: failed to fetch page body:', e);
        }

        // 2. Inline comments
        var commentsCount = 0;
        if (cfg.includeInlineComments !== false && folder) {
            var comments = contentOutput.fetchPageInlineComments(existing.id, pageTitle, 100);
            contentOutput.writeCommentsFiles(folder, comments, contentOutput.COMMENTS_BASE_NAME);
            commentsCount = comments.length;
            console.log('Collected ' + commentsCount + ' inline comment(s) from page ' + existing.id);
        }

        return {
            success: true,
            action: 'context_fetched',
            pageId: existing.id,
            commentsCount: commentsCount
        };
    } catch (error) {
        console.error('Error in fetchConfluenceOutputContext:', error);
        return { success: false, action: 'error', error: error.toString() };
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = { action: action, CURRENT_CONTENT_FILE: CURRENT_CONTENT_FILE, TARGET_MARKER_FILE: TARGET_MARKER_FILE };
}

jobs:
  gate:
    # PR / dispatch on a PR head: always measure. Main-side events (push, merge-bot completion,
    # manual dispatch on main): measure only when the released baseline does not yet cover HEAD.
    runs-on: ubuntu-24.04
    outputs:
      run: ${{ steps.g.outputs.run }}
    steps:
      - id: g
        env:
          GH_TOKEN: ${{ github.token }}
          EVENT: ${{ github.event_name }}
          REF: ${{ github.ref }}
          BOT_CONCLUSION: ${{ github.event.workflow_run.conclusion }}
        run: |
          main_side=false
          [ "$EVENT" = "push" ] || [ "$EVENT" = "workflow_run" ] && main_side=true
          [ "$EVENT" = "workflow_dispatch" ] && [ "$REF" = "refs/heads/main" ] && main_side=true
          if [ "$main_side" != "true" ]; then
            echo "run=true" >> "$GITHUB_OUTPUT"; exit 0      # pull_request / dispatch on a PR head: always measure
          fi
          if [ "$EVENT" = "workflow_run" ] && [ "$BOT_CONCLUSION" != "success" ]; then
            echo "run=false" >> "$GITHUB_OUTPUT"; echo "merge bot run was not successful — skip"; exit 0
          fi
          body="$(gh release view "$BASELINE_TAG" --repo "$GITHUB_REPOSITORY" --json body --jq .body 2>/dev/null || true)"
          if printf '%s' "$body" | grep -q "main@${GITHUB_SHA}"; then
            echo "run=false" >> "$GITHUB_OUTPUT"; echo "baseline already covers ${GITHUB_SHA} — skip"
          else
            echo "run=true" >> "$GITHUB_OUTPUT"
          fi

  crap:
    needs: gate
    if: needs.gate.outputs.run == 'true'
    runs-on: ubuntu-24.04
    steps:
      - uses: actions/checkout@v4

      - uses: actions/setup-node@v4
        with:
          node-version: 20

      - name: Install pinned tools (separate prefix — never node_modules here)
        run: |
          npm install --prefix "$RUNNER_TEMP/tools" --no-fund --no-audit \
            "github:${CRAP4JS_REPO}#${CRAP4JS_REF}" nyc@17

      - name: Instrument the tree (harness eval-loads bypass nyc's hook)
        run: |
          "$RUNNER_TEMP/tools/node_modules/.bin/nyc" instrument --cwd . . \
            "$RUNNER_TEMP/inst"
          # nyc instrument copies only .js — add the json/md/sh payloads the
          # suite reads (configs, instructions, prompts, fixtures).
          rsync -a --exclude '*.js' --exclude '.git' ./ "$RUNNER_TEMP/inst/"
          # (the factory board — and its pristine-app source guard — moved to
          # the dmtools-factory repo; nothing browser-side is text-read here anymore)
          # Tests call `git ls-files` (agentDocsCoverage): give the copied tree a throwaway
          # index of the same tracked files, without the real history.
          (cd "$RUNNER_TEMP/inst" && git init -q && git add -A -f . >/dev/null 2>&1 || true)

      - name: Run the unit suite for coverage (instrumented tree)
        # Canonical green-gate is the dmtools-java runner (pack-release test job); the node
        # harness mirrors it (file_*/cli_*/assert/network-guard parity) and must be green too,
        # so a red harness fails this job instead of being swallowed. ci/run_with_coverage.js
        # wraps the harness and dumps the Istanbul global after the run.
        run: |
          cd "$RUNNER_TEMP/inst"
          FILES="$(node -e "console.log(require('./js/unit-tests/run_all.json').params.jobParams.testFiles.join(' '))")"
          node ci/run_with_coverage.js \
            "$RUNNER_TEMP/inst/js/unit-tests/node_testRunner.js" \
            "$RUNNER_TEMP/cov/coverage-final.json" $FILES

      - name: Fetch the released baseline
        id: baseline
        env:
          GH_TOKEN: ${{ github.token }}
        run: |
          if gh release download "$BASELINE_TAG" --repo "$GITHUB_REPOSITORY" --pattern "$BASELINE_ASSET" \
               --dir "$RUNNER_TEMP/base" --clobber 2>/dev/null && [ -s "$RUNNER_TEMP/base/$BASELINE_ASSET" ]; then
            echo "present=true" >> "$GITHUB_OUTPUT"
            echo "baseline: $(node -e "const b=require('$RUNNER_TEMP/base/$BASELINE_ASSET');console.log(Object.keys(b.functions).length+' functions, max '+b.maxCrap)")"
// Coverage runner for the crap4js quality gate (dmtools-agents).
//
// Executes the node test harness (js/unit-tests/node_testRunner.js) against
// the nyc-INSTRUMENTED copy of the repo and dumps global.__coverage__ in
// Istanbul coverage-final.json format for crap4js.
//
// Why the dance: the harness loads every module through its own
// loadModule()/eval() (mock injection), which bypasses nyc's require hook —
// a plain `nyc node node_testRunner.js` instruments nothing. Pre-instrumenting
// the tree with `nyc instrument` bakes the Istanbul counters into the sources
// themselves, so eval'd code reports coverage through the global.
//
// Usage:
//   node ci/run_with_coverage.js <runner.js> <coverage-out.json> [testFiles...]
//
// Exit code = the harness's exit code (0 = all tests passed). Coverage is
// written regardless of test failures — the canonical suite green-gate is
// the pack-release test job (`dmtools run js/unit-tests/run_all.json`);
// this node harness is a coverage vehicle, and its known mock gaps
// (see the quality workflow) must not block coverage collection.

const fs = require('fs');
const path = require('path');

const runner = process.argv[2];
const outFile = process.argv[3];
const testFiles = process.argv.slice(4);

const origExit = process.exit;
let exitCode = 0;
process.exit = (c) => { exitCode = c || 0; throw { __coverage_exit__: true }; };
process.argv = [process.argv[0], runner].concat(testFiles);

try {
  require(runner);
} catch (e) {
  if (!e || !e.__coverage_exit__) {
    console.error(e);
    origExit(2);
  }
}
fs.mkdirSync(path.dirname(outFile), { recursive: true });
fs.writeFileSync(outFile, JSON.stringify(global.__coverage__ || {}));
console.log('coverage written: ' + outFile + ' (' +
  Object.keys(global.__coverage__ || {}).length + ' files)');
origExit(exitCode);

