        // hold the current Bug hostage.
        if (tracker.hasStage(tc, 'BUG_TO_FIX', jiraConfig.statuses.BUG_TO_FIX)) {
            var linkedBugs = findLinkedBugs(tc.key);
            var hasOtherBug = linkedBugs.some(function(bug) {
