            confluence_sync_markdown_directory: function(args) {
                synced = args;
                return JSON.stringify({ syncedPages: ['index'] });
            }
        }, { space: 'DISC', parentPageId: '123' });

        var result = mod.action(makeParams());

        assert.equal(result.success, true);
