            './common/contentOutput.js': loadModule('js/common/contentOutput.js',
                makeRequire({ '../configLoader.js': { loadProjectConfig: function() { return {}; } }, './trackers.js': trackersMock() }),
                globals)
        }),
        globals
    );
}

function makeParams(overrides) {
