        result.content = result.content.substring(0, idx) +
            IC_OPEN_TAG + anchor.ref + ']]' + anchor.text + IC_CLOSE_TAG +
            result.content.substring(idx + anchor.text.length);
        result.injected.push(anchor.ref);
    });
