        var hit = { title: 'TS-1 fix', head: { ref: 'main' } };
        var later = { title: 'TS-1 again', head: { ref: 'main' } };
        assert.equal(helpers.findOpenTestPr(none, 'TS-1'), null);
        assert.equal(helpers.findOpenTestPr([], 'TS-1'), null);
